validate_accuracy_log() {
    local log="$1"
    awk -F, -v tol="$TOL" '
        $1 == "exp" || $1 == "ref" || $1 == "serial" {
            seen[$1] = 1
            if (($NF - 2) + 0 > tol || ($NF - 1) + 0 > tol || $NF + 0 > tol) bad = 1
        }
        END {
            if (!seen["exp"] || (!seen["ref"] && !seen["serial"]) || bad) exit 1
        }
    ' "$log"
}
